/**
 * Decision ladder (PRD §12): eligible, pending review, unranked because evidence is insufficient,
 * and invalid because a rule was violated. Insufficient GPS is never treated as cheating.
 */
export type Decision = 'eligible' | 'pending_review' | 'unranked' | 'invalid';

